package it.binario.app

import java.net.URI

/**
 * Destinazioni interne esposte dai soli deep link esplicitamente supportati.
 *
 * [TrainSearch] conserva l'assenza del parametro `number`: lo shortcut di sistema
 * deve poter aprire direttamente la modalità di ricerca treno senza inventare una
 * ricerca nazionale o un numero di treno.
 */
sealed interface BinarioDeepLink {
    data object ActiveRoute : BinarioDeepLink
    data object NextDepartures : BinarioDeepLink
    data class TrainSearch(val number: String?) : BinarioDeepLink
}

/** A single, consumable navigation request generated by an Android intent. */
data class DeepLinkRequest(
    val id: Long,
    val deepLink: BinarioDeepLink
)

/**
 * Strict allowlist for external URIs. Parsing accepts only the app's VIEW action,
 * the `binario` scheme, known host/path pairs, and the one documented query field.
 */
object BinarioDeepLinkParser {
    const val viewAction: String = "android.intent.action.VIEW"

    private const val scheme = "binario"
    private val trainNumberQuery = Regex("^number=([A-Za-z0-9]{1,12})$")

    fun parse(action: String?, dataString: String?): BinarioDeepLink? {
        if (action != viewAction || dataString.isNullOrBlank()) return null
        val uri = runCatching { URI(dataString) }.getOrNull() ?: return null
        if (
            uri.scheme != scheme ||
            uri.host == null ||
            uri.rawAuthority != uri.host ||
            uri.userInfo != null ||
            uri.port != -1 ||
            uri.rawFragment != null
        ) return null

        return when (uri.host to uri.rawPath) {
            "route" to "/active" -> if (uri.rawQuery == null) BinarioDeepLink.ActiveRoute else null
            "departures" to "/next" -> if (uri.rawQuery == null) BinarioDeepLink.NextDepartures else null
            "train" to "/search" -> parseTrainSearch(uri.rawQuery)
            else -> null
        }
    }

    private fun parseTrainSearch(rawQuery: String?): BinarioDeepLink? {
        if (rawQuery == null) return BinarioDeepLink.TrainSearch(number = null)
        val number = trainNumberQuery.matchEntire(rawQuery)
            ?.groupValues
            ?.getOrNull(1)
            ?: return null
        return BinarioDeepLink.TrainSearch(number)
    }
}

/**
 * Keeps a deep-link event pending until the UI acknowledges it. Recomposition may
 * observe the same request repeatedly, but only [consume] with its current id can
 * clear it and apply its navigation side effect.
 */
class DeepLinkRequestDispatcher(
    private val parser: (String?, String?) -> BinarioDeepLink? = BinarioDeepLinkParser::parse
) {
    private var nextRequestId = 0L
    private var pendingRequest: DeepLinkRequest? = null

    fun receive(action: String?, dataString: String?): DeepLinkRequest? {
        val deepLink = parser(action, dataString) ?: run {
            pendingRequest = null
            return null
        }
        return DeepLinkRequest(++nextRequestId, deepLink).also { pendingRequest = it }
    }

    fun consume(requestId: Long): Boolean {
        if (pendingRequest?.id != requestId) return false
        pendingRequest = null
        return true
    }

    fun pending(): DeepLinkRequest? = pendingRequest
}
